  funnel: vec4f, // column base y, column top y, neck radius, cloud-deck radius
  storm: vec4f, // swirl rate, axis sway, phase offset, rise speed scale
  water: vec4f, // water level y, swell amplitude, absorption, caustic gain
  air: vec4f, // vortex density, sun shaft gain, sea floor depth, surface glare
